west, south, east, north = lon0-0.03, lat0-0.03, lon0+0.03, lat0+0.03
url=f'https://api.openstreetmap.org/api/0.6/map?bbox={west},{south},{east},{north}'
xml=requests.get(url, headers={'User-Agent':'Mozilla/5.0'}, timeout=60).text
