root=ET.fromstring(xml)
coords={n.attrib['id']:(float(n.attrib['lat']), float(n.attrib['lon'])) for n in root.findall('node')}

R=6371000
lat_scale=111320
lon_scale=111320*math.cos(math.radians(lat0))

def xy(lat,lon):
    return ((lon-lon0)*lon_scale, (lat-lat0)*lat_scale)

def point_seg_dist(px,py, ax,ay, bx,by):
    dx,dy=bx-ax,by-ay
    if dx==0 and dy==0:
        return math.hypot(px-ax,py-ay)
    t=((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)
    t=max(0,min(1,t))
    x=ax+t*dx; y=ay+t*dy
    return math.hypot(px-x,py-y)

road_classes={'motorway','trunk','primary','secondary','tertiary','unclassified','residential','service','track','path'}
road_dists=[]
settle_dists=[]
place_nodes=[]
residential_polys=[]
for way in root.findall('way'):
    tags={t.attrib['k']:t.attrib['v'] for t in way.findall('tag')}
    nds=[coords.get(nd.attrib['ref']) for nd in way.findall('nd')]
    nds=[p for p in nds if p]
    if len(nds)<2: continue
    if tags.get('highway') in road_classes:
        name=tags.get('name','(unnamed)')
        hw=tags.get('highway')
        best=1e18
        for (la1,lo1),(la2,lo2) in zip(nds,nds[1:]):
            ax,ay=xy(la1,lo1); bx,by=xy(la2,lo2)
            d=point_seg_dist(0,0,ax,ay,bx,by)
            if d<best: best=d
        road_dists.append((best, hw, name))
    if tags.get('building') or tags.get('landuse')=='residential':
        pts=[xy(la,lo) for la,lo in nds]
        # distance to polygon edges / building outline
        best=1e18
        for (ax,ay),(bx,by) in zip(pts,pts[1:]):
            d=point_seg_dist(0,0,ax,ay,bx,by)
            if d<best: best=d
        settle_dists.append((best, 'building' if tags.get('building') else 'residential', tags.get('name','')))

for node in root.findall('node'):
    tags={t.attrib['k']:t.attrib['v'] for t in node.findall('tag')}
    if tags.get('place') in {'village','hamlet','suburb','neighbourhood'}:
        la,lo=coords[node.attrib['id']]
        x,y=xy(la,lo)
        place_nodes.append((math.hypot(x,y), tags.get('place'), tags.get('name','')))

