import requests, xml.etree.ElementTree as ET, math, random
from collections import defaultdict
bbox=(78.05,12.55,78.28,12.75)
west,south,east,north=bbox
lat0=(south+north)/2
lon0=(west+east)/2
xml=requests.get(f'https://api.openstreetmap.org/api/0.6/map?bbox={west},{south},{east},{north}', headers={'User-Agent':'Mozilla/5.0'}, timeout=60).text
root=ET.fromstring(xml)
coords={n.attrib['id']:(float(n.attrib['lat']), float(n.attrib['lon'])) for n in root.findall('node')}
lat_scale=111320
lon_scale=111320*math.cos(math.radians(lat0))

def xy(lat,lon):
    return ((lon-lon0)*lon_scale, (lat-lat0)*lat_scale)

def pseg(px,py, ax,ay, bx,by):
    dx,dy=bx-ax,by-ay
    if dx==0 and dy==0:
        return math.hypot(px-ax,py-ay)
    t=((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)
    t=0 if t<0 else 1 if t>1 else t
    x=ax+t*dx; y=ay+t*dy
    return math.hypot(px-x,py-y)

classes={
    'major':{'motorway','trunk','primary','secondary','tertiary'},
    'minor':{'unclassified','residential','service'},
    'trackpath':{'track','path'}
}
segs={k:[] for k in classes}
for way in root.findall('way'):
    tags={t.attrib['k']:t.attrib['v'] for t in way.findall('tag')}
    pts=[coords.get(nd.attrib['ref']) for nd in way.findall('nd')]
    pts=[p for p in pts if p]
    if len(pts)<2: continue
    hw=tags.get('highway')
    xys=[xy(la,lo) for la,lo in pts]
    for k,vals in classes.items():
        if hw in vals:
            segs[k].extend(list(zip(xys,xys[1:])))
CELL=500.0

def build_index(segs):
    idx=defaultdict(list)
    for i,((ax,ay),(bx,by)) in enumerate(segs):
        minx,maxx=sorted((ax,bx)); miny,maxy=sorted((ay,by))
        for gx in range(int(math.floor(minx/CELL)), int(math.floor(maxx/CELL))+1):
            for gy in range(int(math.floor(miny/CELL)), int(math.floor(maxy/CELL))+1):
                idx[(gx,gy)].append(i)
    return idx
idx={k:build_index(v) for k,v in segs.items()}

def md(pt,segs,idx):
    px,py=pt; gx=int(math.floor(px/CELL)); gy=int(math.floor(py/CELL)); best=1e18; seen=set()
    for r in range(0,30):
        hit=False
        for cx in range(gx-r,gx+r+1):
            for cy in range(gy-r,gy+r+1):
                if r and abs(cx-gx)!=r and abs(cy-gy)!=r: continue
                for i in idx.get((cx,cy),()):
                    if i in seen: continue
                    seen.add(i); hit=True
                    (ax,ay),(bx,by)=segs[i]
                    d=pseg(px,py,ax,ay,bx,by)
                    if d<best: best=d
        if hit and best < (r+1)*CELL: break
    return best

fire=xy(12.71561,78.19357)
random.seed(0)
N=1200
samples=[xy(random.uniform(south,north), random.uniform(west,east)) for _ in range(N)]
for k in classes:
    fd=md(fire,segs[k],idx[k])
    arr=[md(p,segs[k],idx[k]) for p in samples]
    pct=sum(x<=fd for x in arr)/N*100
    arr.sort()
    print(k,'fire',round(fd,1),'pct',round(pct,1),'p10',round(arr[int(.1*(N-1))],1),'median',round(arr[int(.5*(N-1))],1))
